package com.ncy.notechaty.data.sync.peer

import com.google.gson.Gson
import com.google.gson.JsonSyntaxException

/**
 * Wire shape of a pairing QR code (or paste-as-text). Generated by the desktop
 * server, consumed by the phone scanner.
 *
 * Wire schema:
 * ```
 * {"v":1,"deviceId":"<uuid>","name":"My Laptop","host":"192.168.1.42","port":8765,
 *  "secret":"<base64-32bytes>"}
 * ```
 */
data class PairingPayload(
    val v: Int,
    val deviceId: String,
    val name: String,
    val host: String,
    val port: Int,
    val secret: String
) {
    fun toJson(): String = Gson().toJson(this)

    fun toPeer(now: Long): SyncPeer = SyncPeer(
        id = deviceId,
        name = name,
        host = host,
        port = port,
        secret = secret,
        pairedAt = now
    )

    companion object {
        const val WIRE_VERSION = 1

        fun parse(text: String): PairingPayload? = try {
            val parsed = Gson().fromJson(text.trim(), PairingPayload::class.java)
            if (parsed == null || parsed.v != WIRE_VERSION) null
            else if (parsed.deviceId.isBlank() || parsed.host.isBlank() ||
                parsed.secret.isBlank() || parsed.port !in 1..65535
            ) null
            else parsed
        } catch (e: JsonSyntaxException) {
            null
        } catch (e: Exception) {
            null
        }
    }
}
